class stringx
{
public:
  int length() const;
  const char *c_str() const;
};

bool operator!=(const stringx &, const stringx &);
bool operator==(const stringx &, const char *);

class chunk_file
{
public:
  const stringx &get_filename() const;
};

template<class T>
void serial_in(chunk_file &, T *);

extern const stringx chunkend_label;
void error(const char *, ...);

class anim_info_id_map_type
{
public:
  void clear();
};

class animation_interface
{
  anim_info_id_map_type anim_info_id_map;
  void read_animations_chunk(chunk_file &, const stringx &);

public:
  void read_animations(chunk_file &, const stringx &);
};

void animation_interface::read_animations(chunk_file &f, const stringx& anims_directory)
{
  anim_info_id_map.clear();

  stringx in;
  for( serial_in(f, &in); in != chunkend_label && in.length() > 0; serial_in(f, &in) )
  {
    if(in == "animations:")
    {
      read_animations_chunk(f, anims_directory);
    }
    else
      error("Bad chunk ID '%s' in %s!", in.c_str(), f.get_filename().c_str());
  }
}
